\documentclass[tikz,border=5pt]{standalone}
\usepackage{amsmath}
\usepackage[T1]{fontenc}
\usepackage{lmodern}
\usetikzlibrary{arrows.meta,calc}

\definecolor{ink}{HTML}{1F2937}
\definecolor{slate}{HTML}{334155}
\definecolor{correction}{HTML}{227C70}
\definecolor{bluefill}{HTML}{EAF3FB}
\definecolor{blueline}{HTML}{829DB4}
\definecolor{baselinefill}{HTML}{EEF2F6}
\definecolor{baselineline}{HTML}{8795A5}
\definecolor{amberfill}{HTML}{FFF3DA}
\definecolor{amberline}{HTML}{B49B63}
\definecolor{tealfill}{HTML}{E7F3EF}
\definecolor{tealline}{HTML}{6B9D92}
\definecolor{evalfill}{HTML}{F1EFF6}
\definecolor{evalline}{HTML}{9892A5}
\definecolor{notegray}{HTML}{4B5563}

\renewcommand{\familydefault}{\sfdefault}
\newcommand{\MathBlock}[1]{%
  {\fontsize{10.5}{13}\selectfont
   \mathsurround=0pt$\displaystyle #1$}}
\newcommand{\Heading}[1]{%
  {\sffamily\bfseries\fontsize{9.5}{11.4}\selectfont #1}}
\newcommand{\PanelContent}[2]{%
  \begin{tabular}{@{}c@{}}
    \Heading{#1}\\[1.4mm]
    \usebox{#2}
  \end{tabular}}

\newsavebox{\InputMath}
\newsavebox{\TargetMath}
\newsavebox{\OnesMath}
\newsavebox{\BaselineMath}
\newsavebox{\ResidualMath}
\newsavebox{\MeanMath}
\newsavebox{\CorrectedMath}
\newsavebox{\CompareMath}
\newsavebox{\MSEMath}

\newsavebox{\InputPanel}
\newsavebox{\TargetPanel}
\newsavebox{\BaselinePanel}
\newsavebox{\ResidualPanel}
\newsavebox{\MeanPanel}
\newsavebox{\CorrectedPanel}
\newsavebox{\EvaluationPanel}
\newsavebox{\AverageText}

\newlength{\PanelPad}
\setlength{\PanelPad}{2.3mm}

\newlength{\ColA}
\newlength{\ColB}
\newlength{\ColC}
\newlength{\ColD}
\newlength{\GapAB}
\newlength{\GapBC}
\newlength{\GapCD}
\newlength{\UpperH}
\newlength{\LeftLowerH}
\newlength{\MeanH}
\newlength{\EvalH}
\newlength{\LowerMaxH}
\newlength{\RowSep}
\newlength{\ChannelY}
\newlength{\InkWidth}
\newlength{\CanvasW}
\newlength{\CanvasH}
\newlength{\LeftMargin}
\newlength{\xA}
\newlength{\xB}
\newlength{\xC}
\newlength{\xD}

% Measure the complete typeset content, including aligned continuation
% lines, superscripts, headings, and mathematical spacing.
\newcommand{\SetColumnWidth}[3]{%
  \setlength{#1}{\wd#2}%
  \ifdim\wd#3>#1\relax
    \setlength{#1}{\wd#3}%
  \fi
  \addtolength{#1}{2\PanelPad}%
}
\newcommand{\IncludeContentHeight}[2]{%
  \ifdim\dimexpr\ht#2+\dp#2+2\PanelPad\relax>#1\relax
    \setlength{#1}{\dimexpr\ht#2+\dp#2+2\PanelPad\relax}%
  \fi
}

\begin{document}
\pagecolor{white}
\color{ink}
\fontsize{9.5}{11.4}\selectfont

\sbox{\InputMath}{\MathBlock{
  \mathbf{x}=(-2,-1,0,1,2)
}}
\sbox{\TargetMath}{\MathBlock{
  \begin{gathered}
    \mathbf{y}=2\mathbf{x}+3\,\mathbf{1}_5\\[1.5pt]
    \mathbf{y}=(-1,1,3,5,7)
  \end{gathered}
}}
\sbox{\OnesMath}{%
  {\fontsize{9}{11}\selectfont
   $\mathbf{1}_5=(1,1,1,1,1)$}}
\sbox{\BaselineMath}{\MathBlock{
  \begin{aligned}
    \widehat{\mathbf{y}}^{(0)}&=2\mathbf{x}\\[1.5pt]
                            &=(-4,-2,0,2,4)
  \end{aligned}
}}
\sbox{\ResidualMath}{\MathBlock{
  \begin{gathered}
    \mathbf{r}=\mathbf{y}-2\mathbf{x}\\[1.5pt]
    \mathbf{r}=(3,3,3,3,3)
  \end{gathered}
}}
\sbox{\MeanMath}{\MathBlock{
  b=\frac{1}{5}\sum_{i=1}^{5}r_i=3
}}
\sbox{\CorrectedMath}{\MathBlock{
  \begin{aligned}
    \widehat{\mathbf{y}}^{\,\mathrm{corr}}
      &=2\mathbf{x}+b\,\mathbf{1}_5\\[1.5pt]
    \widehat{\mathbf{y}}^{\,\mathrm{corr}}
      &=(-1,1,3,5,7)
  \end{aligned}
}}
\sbox{\CompareMath}{\MathBlock{
  \mathbf{y}\quad\text{vs.}\quad
  \widehat{\mathbf{y}}^{\,\mathrm{corr}}
}}
\sbox{\MSEMath}{\MathBlock{
  \begin{aligned}
    \mathrm{MSE}
      &=\frac{1}{5}\sum_{i=1}^{5}
        \left(y_i-\widehat y_i^{\,\mathrm{corr}}\right)^2\\[1.5pt]
      &=0
  \end{aligned}
}}

\sbox{\InputPanel}{%
  \PanelContent{Input observations}{\InputMath}}
\sbox{\TargetPanel}{%
  \begin{tabular}{@{}c@{}}
    \Heading{Observed targets}\\[1.4mm]
    \usebox{\TargetMath}\\[1.0mm]
    \usebox{\OnesMath}
  \end{tabular}}
\sbox{\BaselinePanel}{%
  \PanelContent{Fixed baseline}{\BaselineMath}}
\sbox{\ResidualPanel}{%
  \PanelContent{Observed residuals}{\ResidualMath}}
\sbox{\MeanPanel}{%
  \PanelContent{Mean residual}{\MeanMath}}
\sbox{\CorrectedPanel}{%
  \PanelContent{Corrected prediction}{\CorrectedMath}}
\sbox{\EvaluationPanel}{%
  \begin{tabular}{@{}c@{}}
    \Heading{\shortstack[c]{Evaluate on the same\\five observations}}
      \\[1.3mm]
    \usebox{\CompareMath}\\[1.3mm]
    \usebox{\MSEMath}
  \end{tabular}}
\sbox{\AverageText}{%
  {\sffamily\fontsize{9}{10.8}\selectfont
   \shortstack[c]{average\\residuals}}}

\SetColumnWidth{\ColA}{\InputPanel}{\TargetPanel}
\SetColumnWidth{\ColB}{\BaselinePanel}{\ResidualPanel}
\SetColumnWidth{\ColC}{\MeanPanel}{\MeanPanel}
\SetColumnWidth{\ColD}{\CorrectedPanel}{\EvaluationPanel}

\setlength{\GapAB}{5.5mm}
\setlength{\GapCD}{5.5mm}
% Label padding plus at least 1.5 mm clearance from both neighboring nodes.
\setlength{\GapBC}{\dimexpr\wd\AverageText+4.2mm\relax}
\ifdim\GapBC<16mm
  \setlength{\GapBC}{16mm}
\fi

\setlength{\UpperH}{22.5mm}
\IncludeContentHeight{\UpperH}{\InputPanel}
\IncludeContentHeight{\UpperH}{\BaselinePanel}
\IncludeContentHeight{\UpperH}{\CorrectedPanel}

\setlength{\LeftLowerH}{27mm}
\IncludeContentHeight{\LeftLowerH}{\TargetPanel}
\IncludeContentHeight{\LeftLowerH}{\ResidualPanel}
\setlength{\MeanH}{23mm}
\IncludeContentHeight{\MeanH}{\MeanPanel}
\setlength{\EvalH}{34mm}
\IncludeContentHeight{\EvalH}{\EvaluationPanel}

\setlength{\LowerMaxH}{\LeftLowerH}
\ifdim\MeanH>\LowerMaxH
  \setlength{\LowerMaxH}{\MeanH}
\fi
\ifdim\EvalH>\LowerMaxH
  \setlength{\LowerMaxH}{\EvalH}
\fi

\setlength{\RowSep}{%
  \dimexpr\UpperH/2+\LowerMaxH/2+5.5mm\relax}
\setlength{\ChannelY}{%
  \dimexpr-\RowSep-\LowerMaxH/2-5.5mm\relax}
\setlength{\InkWidth}{%
  \dimexpr\ColA+\GapAB+\ColB+\GapBC+\ColC+\GapCD+\ColD\relax}

% Preserve the type sizes; expand the width if the measured content needs it.
\setlength{\CanvasW}{18cm}
\ifdim\InkWidth>\CanvasW
  \setlength{\CanvasW}{\InkWidth}
\fi
% Including standalone's 5 pt border, the white page has a 16:9 ratio.
\setlength{\CanvasH}{.5625\CanvasW}
\addtolength{\CanvasH}{-4.375pt}
\setlength{\LeftMargin}{\dimexpr\CanvasW/2-\InkWidth/2\relax}

\setlength{\xA}{\dimexpr\LeftMargin+\ColA/2\relax}
\setlength{\xB}{\dimexpr\LeftMargin+\ColA+\GapAB+\ColB/2\relax}
\setlength{\xC}{%
  \dimexpr\LeftMargin+\ColA+\GapAB+\ColB+\GapBC+\ColC/2\relax}
\setlength{\xD}{\dimexpr\LeftMargin+\InkWidth-\ColD/2\relax}

\begin{tikzpicture}[
  panel/.style={
    rectangle,
    rounded corners=2mm,
    line width=.7pt,
    inner xsep=\PanelPad,
    inner ysep=\PanelPad,
    outer sep=0pt,
    align=center,
    text=ink
  },
  dependency/.style={
    line width=.9pt,
    line cap=round,
    line join=round,
    shorten <=.6pt,
    shorten >=.6pt,
    -{Latex[length=2mm,width=1.45mm]}
  },
  supplied/.style={dependency,draw=slate},
  adjustment/.style={dependency,draw=correction},
  edge label/.style={
    font=\sffamily\fontsize{9}{10.8}\selectfont,
    text=ink,
    fill=white,
    inner xsep=.6mm,
    inner ysep=.35mm,
    outer sep=0pt,
    align=center
  }
]

\node[panel,fill=bluefill,draw=blueline,
      minimum width=\ColA,minimum height=\UpperH]
  (input) at (\xA,0) {\usebox{\InputPanel}};

\node[panel,fill=bluefill,draw=blueline,
      minimum width=\ColA,minimum height=\LeftLowerH]
  (targets) at (\xA,-\RowSep) {\usebox{\TargetPanel}};

\node[panel,fill=baselinefill,draw=baselineline,
      minimum width=\ColB,minimum height=\UpperH]
  (baseline) at (\xB,0) {\usebox{\BaselinePanel}};

\node[panel,fill=amberfill,draw=amberline,
      minimum width=\ColB,minimum height=\LeftLowerH]
  (residuals) at (\xB,-\RowSep) {\usebox{\ResidualPanel}};

\node[panel,fill=tealfill,draw=tealline,
      minimum width=\ColC,minimum height=\MeanH]
  (mean) at (\xC,-\RowSep) {\usebox{\MeanPanel}};

\node[panel,fill=tealfill,draw=tealline,
      minimum width=\ColD,minimum height=\UpperH]
  (corrected) at (\xD,0) {\usebox{\CorrectedPanel}};

\node[panel,fill=evalfill,draw=evalline,
      minimum width=\ColD,minimum height=\EvalH]
  (evaluation) at (\xD,-\RowSep) {\usebox{\EvaluationPanel}};

% 1. Supplied inputs to the fixed baseline.
\draw[supplied] (input.east) -- (baseline.west);

% 2. Baseline values used to calculate observed residuals.
\draw[supplied] (baseline.south) -- (residuals.north);

% 3. Observed targets used to calculate residuals.
\draw[supplied] (targets.east) -- (residuals.west);

% 4. Residual averaging.
\draw[adjustment]
  (residuals.east)
  -- node[edge label,midway,above=1.5mm]
       {\usebox{\AverageText}}
  (mean.west);

% 5. Baseline contribution to the corrected prediction.
\draw[supplied]
  ($(baseline.east)+(0,3.5mm)$)
  -- node[edge label,midway,above=1.5mm]
       {\MathBlock{2\mathbf{x}}}
  ($(corrected.west)+(0,3.5mm)$);

% 6. Scalar correction, entering through a separate lower left port.
\draw[adjustment,rounded corners=1.6mm]
  (mean.north)
  -- (\xC,-5.5mm)
  -- node[edge label,midway,above=1.5mm]
       {\MathBlock{b=3}}
  ($(corrected.west)+(0,-5.5mm)$);

% 7. Corrected values passed to evaluation.
\draw[supplied] (corrected.south) -- (evaluation.north);

% 8. A dedicated channel carries the same observed targets to evaluation.
\draw[supplied,rounded corners=1.8mm]
  (targets.south)
  -- (\xA,\ChannelY)
  -- node[edge label,midway,below=1.5mm]
       {observed targets: same five points}
  (\xD,\ChannelY)
  -- (evaluation.south);

\node[
  anchor=north,
  inner sep=0pt,
  outer sep=0pt,
  text=notegray,
  font=\sffamily\fontsize{9}{11}\selectfont
] (scope) at (.5\CanvasW,{\ChannelY-7.8mm})
  {The correction is computed and evaluated on these same five observations.};

% Center the compact drawing and scope note on the white 16:9 canvas.
\path
  let \p1=($(input.north)!.5!(scope.south)$)
  in coordinate (canvascenter) at (.5\CanvasW,\y1);

\pgfresetboundingbox
\path[use as bounding box]
  ([xshift=-.5\CanvasW,yshift=-.5\CanvasH]canvascenter)
  rectangle
  ([xshift=.5\CanvasW,yshift=.5\CanvasH]canvascenter);

\end{tikzpicture}
\end{document}
